// generated by amp-mgui's configure from its resource/app-theme*.ts: edit that and reconfigure, not this

// The page's theme follows prefers-color-scheme: data-theme="dark" on <html> while it answers
// dark, no data-theme while it answers light. Inside Sobamail the media feature answers
// Sobamail's own theme -- the host emulates it for every view it shows (amp-cef
// CefClientImpl, apply_reader_color_scheme) -- and elsewhere the OS's. An app calls it from its
// entry point, before mounting, and declares <meta name="color-scheme" content="light dark">,
// which keeps Chromium's auto-darkening off a page with a dark theme of its own.
export function follow_color_scheme(
    root: HTMLElement = document.documentElement,
    query: MediaQueryList | undefined = globalThis.matchMedia?.('(prefers-color-scheme: dark)'),
): void {
    if (!query) {
        return; // no media queries (a bare test environment): the light theme
    }

    const apply = (dark: boolean) => {
        if (dark) {
            root.dataset.theme = 'dark';
        } else {
            delete root.dataset.theme;
        }
    };

    apply(query.matches);
    query.addEventListener('change', (e) => apply(e.matches));
}
